[9222]={["atomIDs"]={"9222:description:1-18","9222:description:20-120","9222:description:125-234","9222:description:236-336","9222:objective:1-124"},["opening"]="The more powerful cache selection carried a particularly severe surcharge for friendly standing. Breechlock advised improving that standing before paying one hundred ten insignias of each kind.",["pending"]="{actor} intended to provide both sets of one hundred ten insignias.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} fulfilled the higher cache exchange at friendly standing.",["sourceHash"]="5cb9bda758871728f950eb66f6b37ac1332b814b1b7de083843961557723ce78",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
