[9224]={["atomIDs"]={"9224:description:1-18","9224:description:20-120","9224:description:125-231","9224:description:233-333","9224:objective:1-122"},["opening"]="The greater-power cache remained expensive even for an honored member. Its exchange required seventy-five Dawn insignias matched by the same number from the Crusade.",["pending"]="{actor} meant to deliver seventy-five insignias of each kind.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} fulfilled the higher honored-standing exchange.",["sourceHash"]="fa8c9f9b9a3bbdf2c482ff17b50b2292188737eaaabbfc0921f32d215a600cf9",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
