[9226]={["atomIDs"]={"9226:description:1-18","9226:description:20-114","9226:description:119-194","9226:description:196-230","9226:objective:1-120"},["opening"]="For the ordinary cache choice, revered standing brought a price Breechlock considered reasonable. Seven insignias from the Dawn and seven from the Crusade would satisfy it.",["pending"]="{actor} planned to offer seven of each insignia.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the revered cache exchange.",["sourceHash"]="63bfe70859f97d2113c41580f93e23d418ca84095a2d67b3813d0a0f9b7ad4cb",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
