[9229]={["aftermath"]="The ring alone left the warrior's fate ominous rather than certain. Korfax believed the damaged band might still be restored.",["atomIDs"]={"9229:description:1-103","9229:description:105-174","9229:description:179-266","9229:description:268-325","9229:description:327-431","9229:description:433-449","9229:description:454-503","9229:objective:1-50"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"9229:completion:1-15","9229:completion:17-36","9229:completion:38-78","9229:completion:83-100","9229:completion:105-142","9229:completion:144-163","9229:completion:165-188"},["minimumStage"]=2,["objectiveSummary"]="Search Naxxramas for Ramaladni's fate.",["opening"]="Ramaladni had studied under Mograine before the Dawn existed. News of his teacher's death drove him into Naxxramas seeking vengeance, and Korfax feared that rage had carried the warrior somewhere from which he would never return.",["pending"]="{actor} would seek evidence of Ramaladni inside Naxxramas.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} brought Ramaladni's ruined ring to Korfax.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="6454d20e2918819502b5983d335973fefdd2299025d90fa695829d6922593ac7",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[9230]={["aftermath"]="Korfax restored the ring and praised the finished work in Ramaladni's name.",["atomIDs"]={"9230:description:1-55","9230:description:57-150","9230:description:152-249","9230:description:251-319","9230:objective:1-130"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"9230:completion:1-44","9230:completion:46-75"},["minimumStage"]=2,["objectiveSummary"]="Bring Korfax a frozen rune, blue sapphire and arcanite bar.",["opening"]="Ramaladni's recovered ring had been made with the runes that formed inside Scourge structures. Repairing it required another such rune, joined with a sapphire and arcanite, rather than ordinary metalwork alone.",["pending"]="{actor} would gather the materials for Korfax's repair.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} supplied Korfax with the rune, sapphire and bar.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="b784edcd9ad6b048f919c22c61b7e8b54494a1f52ab4322726de17f9a5985d9b",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[9232]={["aftermath"]="Wilhelm finished the hard work with a grim joke about facing death in clean clothes.",["atomIDs"]={"9232:description:1-42","9232:description:44-114","9232:description:116-177","9232:description:182-197","9232:description:202-227","9232:description:229-277","9232:description:282-313","9232:description:315-342","9232:description:344-423","9232:objective:1-163"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"9232:completion:1-40","9232:completion:45-66","9232:completion:68-87","9232:completion:89-128"},["minimumStage"]=2,["objectiveSummary"]="Supply Wilhelm with two frozen runes, two water essences, two sapphires and thirty gold.",["opening"]="Wilhelm doubted how long another hopeful defender would survive Naxxramas, but offered what help he could. Omarion had left him one recipe with several variations, and materials plus payment would turn it into useful clothing.",["pending"]="{actor} would bring Wilhelm the supplies for his surviving recipe.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} fulfilled Wilhelm's crafting request.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="4e47e5ece6e8406cdb2a75afd8d9355f4560c79da58eb513e31931639176cbff",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[9233]={["aftermath"]="Wilhelm protested that he and Omarion had been close friends, then recognized the new crafts the recipes would permit for a fee.",["atomIDs"]={"9233:description:1-8","9233:description:13-63","9233:description:65-175","9233:description:177-274","9233:description:279-327","9233:description:329-379","9233:description:381-473","9233:description:478-488","9233:description:493-499","9233:objective:1-95"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"9233:completion:1-55","9233:completion:57-97","9233:completion:102-160","9233:completion:162-245"},["minimumStage"]=2,["objectiveSummary"]="Deliver Omarion's handbook to Wilhelm.",["opening"]="Omarion's final note preserved the rest of his recipes while insulting Wilhelm's craftsmanship. He ordered that the bearer be supplied with requested work, expecting that his old associate would still demand substantial payment.",["pending"]="{actor} would take Omarion's recipes to Wilhelm.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the handbook to Wilhelm.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="6c9b8e93d76178300f5cddcdcc10007ef58d8327475b3d55626289d8d76e9ae1",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
