[9250]={["aftermath"]="Anachronos spoke of the archmages' deaths and the staff's arrival as matters of fate.",["atomIDs"]={"9250:description:1-46","9250:description:48-99","9250:description:101-184","9250:description:189-293","9250:objective:1-102"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"9250:completion:1-24","9250:completion:29-59","9250:completion:61-86","9250:completion:88-145"},["minimumStage"]=2,["objectiveSummary"]="Find help to recover Atiesh's missing head and base and cleanse its evil.",["opening"]="The assembled frame left Atiesh nearly whole, but its head and base were still absent. More dangerously, the Guardian's staff remained a conduit for Sargeras's evil, requiring wisdom beyond simply joining its pieces.",["pending"]="{actor} would seek someone able to guide the recovery and cleansing.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} brought the frame to Anachronos.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="55577a1af3f4109a11964d51f544f9415b8de7417650c926ee19531fd14850ec",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[9251]={["aftermath"]="Anachronos sensed an otherworldly being inside the restored staff, leaving exorcism as the remaining danger.",["atomIDs"]={"9251:description:1-37","9251:description:39-99","9251:description:101-128","9251:description:130-149","9251:description:154-210","9251:description:212-270","9251:description:275-368","9251:description:370-422","9251:description:427-489","9251:objective:1-99"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"9251:completion:1-26","9251:completion:28-53"},["minimumStage"]=2,["objectiveSummary"]="Bring Atiesh's head and base to Anachronos.",["opening"]="Anachronos placed the staff's head with Kel'Thuzad and its base in Ahn'Qiraj, where Brann had left it after his expedition. Reuniting the pieces meant entering two hostile strongholds while the staff's own evil remained unresolved.",["pending"]="{actor} would recover the head and base of Atiesh.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered both missing pieces to Anachronos.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="e7d314e88bf51334a073862d4e6184f30c15fe95f80d3e4b5a2fe3239534a2e2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
