[9310]={["aftermath"]="Rukag suspected an attempt to create a camp inside the Undercity and urged continued vigilance.",["atomIDs"]={"9310:description:1-96","9310:objective:1-87"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"9310:completion:1-55","9310:completion:60-152","9310:completion:154-211","9310:completion:213-254"},["minimumStage"]=2,["objectiveSummary"]="Bring the faint necrotic crystal to Rukag in the Undercity.",["opening"]="The wight's remains yielded a crystal still radiating faint deathly energy. Taking it to the lieutenant could connect the local attack to the Scourge's wider use of necropolis camps.",["pending"]="{actor} would bring the crystal to Lieutenant Rukag.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the crystal to Rukag.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="a5ace568a4e68177999b08639915402b7dfa38a5b1a5c5af891b289da63ef323",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[9319]={["atomIDs"]={"9319:description:1-56","9319:description:58-111","9319:description:113-164","9319:description:169-229","9319:description:231-388","9319:objective:1-140"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["minimumStage"]=2,["objectiveSummary"]="Touch the festival fires in Blackrock Spire, Dire Maul, Scholomance and Stratholme.",["opening"]="The Flamekeeper claimed that even the darkest places shared in the season's fire. Visiting bonfires inside four hostile strongholds would reveal that unexpected reach of the celebration.",["pending"]="{actor} would seek the four dungeon bonfires.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} visited the four fires and returned to the Flamekeeper.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="420bafa87fa68ee8f3840236f3d7ea1c0c8556cf6efcf9b070767011bdf3ff2f",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[9322]={["aftermath"]="The Flamekeeper welcomed the traveler back and offered a reminder of the fires' warmth.",["atomIDs"]={"9322:description:1-114","9322:description:116-171","9322:description:176-265","9322:description:267-431","9322:description:433-469","9322:objective:1-130"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"9322:completion:1-64","9322:completion:66-94","9322:completion:96-171"},["minimumStage"]=2,["objectiveSummary"]="Visit the festival camps in Azshara, Silithus, Un'Goro and Winterspring.",["opening"]="Kalimdor's blue festival fires offered a journey across sharply different lands: the cold west of Winterspring, northeastern Azshara, the wastes near Valor's Rest and the lush crater's entrance. The Flamekeeper wanted those distant flames witnessed.",["pending"]="{actor} would travel to the four Kalimdor camps.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned after visiting the four fires.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="60e478fb0e85de0c39b9e71c3aca583a98a86e9941770c30dc5dcd110c5d9646",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
