[9362]={["aftermath"]="Xylem found its aura strange and proposed testing its magical capacities as part of the reward.",["atomIDs"]={"9362:description:1-26","9362:description:29-87","9362:description:90-190","9362:description:195-303","9362:description:306-372","9362:objective:1-48","9362:objective:51-109"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"9362:completion:1-42","9362:completion:44-152"},["minimumStage"]=2,["objectiveSummary"]="Recover Krellian's prismatic shell for Xylem.",["opening"]="Xylem's scrying found powerful magic in an artifact held by Krellian at Zin-Malor's temple. Unable to leave his own tower, he demanded the warlord's death and the shell's recovery for study.",["pending"]="{actor} would seek Krellian's prismatic shell.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the shell to Xylem.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="65c7d9db9fff24cda7e5b04e9f1e2a7e165e250c7576e19d543592f7e00067cb",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[9364]={["aftermath"]="Xylem declared the gathered magic ready to be reformed into a new spell.",["atomIDs"]={"9364:description:1-66","9364:description:71-144","9364:description:147-274","9364:description:277-359","9364:description:364-403","9364:objective:1-89","9364:objective:92-168"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"9364:completion:1-9","9364:completion:11-19","9364:completion:24-77","9364:completion:79-85"},["minimumStage"]=2,["objectiveSummary"]="Use the shell with polymorph and defeat fifty Spitelash clones.",["opening"]="Xylem's research suggested that the shell's chaotic aura would split polymorphed Spitelash into temporary clones. Destroying those copies would gather their essence in the shell for a further magical experiment.",["pending"]="{actor} would test the shell on the Spitelash and collect the clones' essence.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the clone experiment and returned to Xylem.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="64429407bde4921cb1960db26bdd640eac5d05555cb8b0a5d36c63281d7873ac",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[9367]={["aftermath"]="The Loremaster credited the appointed keepers with tending the fires well and thanked the inspector.",["atomIDs"]={"9367:description:1-32","9367:description:37-135","9367:description:137-274","9367:description:279-328","9367:description:330-398","9367:description:400-475","9367:objective:1-125"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"9367:completion:1-10","9367:completion:12-113","9367:completion:115-198"},["minimumStage"]=2,["objectiveSummary"]="Inspect the capital bonfires in Stormwind, Ironforge and Darnassus.",["opening"]="The festival's chosen Flamekeepers were charged with making the capitals' fires bright enough to honor the season. The Loremaster needed someone to travel between the cities and confirm that the fires burned properly.",["pending"]="{actor} would inspect the three Alliance capital fires.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} reported the capital bonfires burning to the Loremaster.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="74bd249127a69a089006446d47e62310378c0caef0b263e7bc2042c0923e89f8",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[9368]={["atomIDs"]={"9368:description:1-32","9368:description:37-135","9368:description:137-274","9368:description:279-328","9368:description:330-398","9368:description:400-475","9368:objective:1-134"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["minimumStage"]=2,["objectiveSummary"]="Inspect the capital bonfires in Orgrimmar, Thunder Bluff and the Undercity.",["opening"]="The Talespinner wanted confirmation that the chosen Flamekeepers had properly tended the Horde capitals' fires. Traveling among the three cities would test whether each bonfire honored the season with sufficient heat and light.",["pending"]="{actor} would inspect the three Horde capital fires.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} reported the three bonfires burning to the Talespinner.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="95d81014cb037f999d76e6ca1d3e40955f188d245b7011ed04cdf532a73b3f78",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability","endingTextConflictsWithFestivalObjective"}},
[9386]={["atomIDs"]={"9386:description:1-25","9386:description:27-98","9386:description:103-250","9386:objective:1-141"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["minimumStage"]=2,["objectiveSummary"]="Revisit the festival bonfires in the four named strongholds.",["opening"]="The Flamekeeper offered another reward for a journey into the depths. The fires in the Spire, Dire Maul, Scholomance and Stratholme again marked the route of the undertaking.",["pending"]="{actor} would return to the four dungeon fires.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} visited the four bonfires and reported back.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="18ea0cba4327d92b18a3bb4b16b76b82cb6e449c8d837133c6339aa7b73e9669",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[9388]={["aftermath"]="The Flamekeeper was relieved that the difficult fires had not gone out before their time.",["atomIDs"]={"9388:description:1-61","9388:description:63-163","9388:description:165-242","9388:description:247-483","9388:objective:1-128"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"9388:completion:1-28","9388:completion:30-102","9388:completion:104-126","9388:completion:128-154"},["minimumStage"]=2,["objectiveSummary"]="Check the green fires in Ashenvale, the Barrens, Darkshore and Stonetalon.",["opening"]="The emerald festival flames needed unusually close tending. Their route led near Ratchet, the Master's Glaive, Silverwing's bridge and the road to Windshear, making their continued burning the purpose of another journey.",["pending"]="{actor} would inspect the four green Kalimdor fires.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} confirmed the four emerald flames still burned.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="db2a433f24118b753c3c9e6f05d4cda488c3b0fced622e410452e0da7d4ae748",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[9389]={["aftermath"]="The Flamekeeper welcomed the account of the rare flames and offered payment for the trouble.",["atomIDs"]={"9389:description:1-85","9389:description:87-202","9389:description:207-276","9389:description:278-470","9389:objective:1-135"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"9389:completion:1-75","9389:completion:77-98","9389:completion:100-141","9389:completion:143-210","9389:completion:212-249"},["minimumStage"]=2,["objectiveSummary"]="Inspect the green fires in Hillsbrad, Silverpine, Westfall and the Wetlands.",["opening"]="The hardest festival fires to maintain burned green. Those in the Eastern Kingdoms lay near Dun Modr, Pyrewood, Westfall's lighthouse cliffs and Hillsbrad's ruined tower, offering a scattered route for their inspection.",["pending"]="{actor} would check the four emerald fires across the Eastern Kingdoms.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned after inspecting the four green fires.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="114acf47d0c65a82c50a6f26c7ca6e0d699b49fea93c79c83d5dec85eefbccb0",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[9415]={["aftermath"]="Bluewall described difficulty matching the Horde's steady northern reinforcements.",["atomIDs"]={"9415:description:1-40","9415:description:42-59","9415:description:64-88","9415:description:90-127","9415:description:129-160","9415:description:165-208","9415:objective:1-70"},["endingAtomIDs"]={"9415:completion:1-48","9415:completion:50-189","9415:completion:194-229"},["opening"]="Torrig directed new recruits toward the Alliance's desert command. Deaths and the risk of drying out framed the welcome before Bluewall could explain the situation.",["pending"]="{actor} intended to report to Bluewall near the hive.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} reached the marshal.",["sourceHash"]="ddfdf94e087f9971a0b54afbb8121128efbdeb123658317eb55793597e299c60",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[9416]={["atomIDs"]={"9416:description:1-49","9416:description:51-80","9416:description:82-118","9416:description:123-251","9416:description:256-294","9416:description:296-339","9416:objective:1-66"},["opening"]="Bloodfist sought recruits rather than offering their training. Desert attrition and daily dwarven reinforcements made the report to Kirika urgent in the struggle for resources.",["pending"]="{actor} planned to seek Kirika's instructions.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} reported to the general.",["sourceHash"]="c23368a6cd14c80d71fe80ea8cda6891784bf140ee61aa9ee1e0fbea21d1ba58",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[9419]={["aftermath"]="The marshal welcomed the success while regretting the late start.",["atomIDs"]={"9419:description:1-118","9419:description:120-206","9419:description:211-308","9419:description:313-412","9419:objective:1-130"},["endingAtomIDs"]={"9419:completion:1-36","9419:completion:41-122","9419:completion:124-202"},["opening"]="Bluewall admitted the Alliance had underestimated the desert's resources while the Horde gathered them. Silithyst recovery now formed a race to catch up and deny stock to the rival force.",["pending"]="{actor} meant to deliver silithyst to the extractor and report.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the extraction delivery for Bluewall.",["sourceHash"]="ab7559d57ca6b8bf22a68fa63a4b3dd3d8820e55505a2d2d222161d6b8bbdc62",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[9422]={["aftermath"]="Kirika counted the stock as a gain for her force and a loss for its rival.",["atomIDs"]={"9422:description:1-85","9422:description:87-210","9422:description:215-286","9422:description:288-378","9422:description:383-426","9422:description:428-447","9422:objective:1-125"},["endingAtomIDs"]={"9422:completion:1-21","9422:completion:23-121"},["opening"]="Kirika described an established resource operation newly challenged by the Alliance. The enemy's arrival turned heat, dust and wildlife from the only obstacles into part of a wider contest.",["pending"]="{actor} intended to bring silithyst to the Horde extractor.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the delivery and spoke with Kirika.",["sourceHash"]="b44d83be2690bce11f76ddf9c837cc825f1beecad2c91ffdac83781b651b5951",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[9664]={["aftermath"]="Whitebeard stressed that they still had to be held against attacks until reinforcements could secure them.",["atomIDs"]={"9664:description:1-31","9664:description:33-135","9664:description:137-273","9664:description:278-373","9664:description:375-428","9664:objective:1-166"},["endingAtomIDs"]={"9664:completion:1-14","9664:completion:16-187"},["opening"]="Whitebeard described an Alliance decision to rebuild abandoned Lordaeron towers as eastern fortifications. Capturing four sites would establish the intended line against enemies holding the west.",["pending"]="{actor} planned to capture the four named towers.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed Whitebeard's tower assignment.",["sourceHash"]="a3bfc6ffbecd29da40df3ed5153a898f93a710b9b8557de398d36b43bf21e7ab",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[9665]={["aftermath"]="Gormok expected a continuing struggle and hoped for further aid until the Alliance was fully driven back.",["atomIDs"]={"9665:description:1-146","9665:description:151-299","9665:description:301-456","9665:objective:1-162"},["endingAtomIDs"]={"9665:completion:1-22","9665:completion:24-137","9665:completion:142-208"},["opening"]="Forsaken agents had discovered the Alliance's tower plans. Gormok sought both the removal of any occupied positions and defense of those already held by the Horde.",["pending"]="{actor} meant to secure the four towers for Gormok.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the Horde tower assignment.",["sourceHash"]="0825938898c4c32a7047bdd5e8b2510dcb87d9d2157d3da832e1ea7a7fb930cf",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[93739]={["atomIDs"]={"93739:objective:1-68","93739:objective:70-180"},["editorialNotes"]="Only two coherent objective atoms survive in the historical69913 reference. Current Tierhall70170 title is corrupt and supplies no story body. Positive catalog XP does not prove availability, current giver, response, or the purpose of the meetings.",["opening"]="Nazgrel is the first contact for a round of meetings across the Horde's leadership. His instructions lead onward to Vol'jin, Cairne Bloodhoof and Sylvanas Windrunner.",["pending"]="{actor} would obtain Nazgrel's instructions and meet the three named leaders.",["readyForFullFieldCompletion"]=false,["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} completed the instructed round of meetings.",["sourceHash"]="88a4854d1a503ff1c24a6e1c60f57594132b25dda1fd19be02db4460025e5c86",["sourceStageStatus"]="OBJECTIVE_ONLY_SETUP_AND_COMPLETION_SOURCE_BLOCKED",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["title"]="Exploring the Horde"},
